// Split LinkedIn job-alert emails into one item per job.
const out = [];
// One timestamp per execution, not per item: two copies of the same job in the
// same email then produce byte-identical items, so any dedupe compare works.
const runAt = new Date().toISOString();

for (const item of $input.all()) {
  const text = (item.json.text || '').replace(/\r/g, '');
  const alertMatch = text.match(/Your job alert for (.+?) in ([^\n]+)/);
  const alert = alertMatch ? alertMatch[1].trim() : '';
  const blocks = text.split(/\n-{10,}\n/);        // jobs are separated by dashed lines
  let found = 0;

  for (const block of blocks) {
    const idMatch = block.match(/linkedin\.com\/(?:comm\/)?jobs\/view\/(\d+)/);
    if (!idMatch) continue;                         // skip header, "See all jobs", footer
    const lines = block
      .split('\n')
      .map(l => l.trim())
      .filter(l => l
        && !l.startsWith('View job:')
        && l !== 'This company is actively hiring'
        && !l.startsWith('Your job alert for')
        && !/new jobs? match/i.test(l));
    const [title = '', company = '', location = ''] = lines;
    found++;
    out.push({
      json: {
        jobId: idMatch[1],
        title,
        company,
        location,
        activelyHiring: block.includes('This company is actively hiring'),
        url: `https://www.linkedin.com/jobs/view/${idMatch[1]}/`,   // clean link, tracking removed
        alert,
        emailDate: item.json.date || '',
        parseOk: Boolean(title && company && location),              // flags a block that didn't parse
        addedAt: runAt,
      },
    });
  }

  // Silent-failure guard. An alert email that yields no jobs means LinkedIn
  // changed the email format. Without this the run succeeds and writes nothing,
  // and you would only notice weeks later from an empty sheet.
  if (found === 0) {
    const msgId = item.json.id || item.json.messageId || runAt;
    out.push({
      json: {
        jobId: `PARSE-FAIL-${msgId}`,
        title: 'PARSE FAILURE - alert email produced 0 jobs',
        company: '',
        location: '',
        activelyHiring: false,
        url: '',
        alert,
        emailDate: item.json.date || '',
        parseOk: false,
        addedAt: runAt,
        status: 'PARSE_FAILURE',
      },
    });
  }
}

// Dedupe WITHIN this batch. The Remove Duplicates node downstream is set to
// "Remove Items Processed in Previous Executions", which by design only compares
// against earlier runs -- n8n's docs are explicit that items repeated within the
// current input are not removed there. A single digest can list the same job
// twice, and the two copies are not byte-identical (the "actively hiring" line
// appears on one and not the other), so comparing all fields would miss them.
// Comparing the job id is the only thing that works.
const seen = new Set();
const deduped = out.filter((o) => {
  if (seen.has(o.json.jobId)) return false;
  seen.add(o.json.jobId);
  return true;
});

return deduped;

// Batch every job from this run into ONE Gemini call.
// 30-ish jobs per run at ~20 alert emails a day: one call keeps us far inside
// the free tier and gives the model the whole set to compare against.
const items = $input.all();

const instructions = `You are triaging LinkedIn job alerts for a working student in Germany.

You see ONLY the job title, company and location from an alert email. You cannot see
the job description. Judge conservatively: mark "skip" only when the TITLE ALONE makes
the job clearly wrong. When in doubt mark "keep" - a later step reads the full description.

Candidate:
- Student, M.Sc. Industrial AI from October 2026. Wants Werkstudent / Praktikum / part-time.
- Full-time is fine if remote or hybrid. That is never visible in a title, so never skip on it.
- Evidence: Python, automation, web scraping, REST APIs, dashboards, SQL, Android (Java/Kotlin),
  C#/.NET, and an LLM pipeline with tests and CI.
- Weak: mathematics, embedded C/C++, React/TypeScript, ML research.
- German A2, English fluent.

Mark "skip" only for titles clearly outside software, data, AI or automation - for example
marketing, sales, HR, finance, law, mechanical or electrical engineering, construction,
logistics, nursing, or graphic design.

Give each job one lane: python, data, ai, automation, dotnet, android, other.

Return ONLY a JSON array. No prose, no markdown fence:
[{"jobId":"<id>","lane":"<lane>","verdict":"keep","reason":"<max 8 words>"}]`;

const listing = items
  .map(i => `${i.json.jobId} | ${i.json.title} | ${i.json.company} | ${i.json.location}`)
  .join('\n');

const geminiBody = {
  contents: [{ parts: [{ text: `${instructions}\n\nJobs:\n${listing}` }] }],
  generationConfig: {
    temperature: 0,                    // triage should be repeatable, not creative
    responseMimeType: 'application/json',
  },
};

return [{ json: { geminiBody, jobCount: items.length } }];

// Merge Gemini's triage back onto the job rows.
// The originals come from the dedupe node, not from Gemini, so a bad or missing
// AI response can never drop a job.
const originals = $('Remove Duplicates').all();

let verdicts = [];
try {
  const raw = $input.first().json?.candidates?.[0]?.content?.parts?.[0]?.text ?? '';
  const cleaned = raw.replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
  const start = cleaned.indexOf('[');
  const end = cleaned.lastIndexOf(']');
  if (start !== -1 && end > start) {
    verdicts = JSON.parse(cleaned.slice(start, end + 1));
  }
} catch (e) {
  verdicts = [];        // quota hit, timeout, junk reply: fall through
}

const byId = new Map(verdicts.map(v => [String(v.jobId), v]));
const aiWorked = verdicts.length > 0;

return originals.map(o => {
  const v = byId.get(String(o.json.jobId));
  return {
    json: {
      ...o.json,
      lane: v?.lane ?? '',
      // Default to keep. Losing a real job to an AI failure is far worse
      // than carrying a few extra rows in the sheet.
      aiVerdict: v?.verdict ?? 'keep',
      aiReason: v?.reason ?? (aiWorked ? 'not returned by model' : 'ai unavailable'),
    },
  };
});
